program.compute:
options = read('/input/options')
ids = [row['id'] for row in options]
result = []
for k in range(3, 6):
    for group in combinations(ids, k):
        chosen = list(group)
        if valid(chosen):
            result = chosen
            break
    if len(result) > 0:
        break

program.effects:
saved = read('/output/selection')
if saved is None:
    write('/output/selection', result)
selection = read('/output/selection')
if status('report') == 'not_sent':
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

